use std::cell::RefCell;
use crate::histogram::{self, Hist};
struct Collector { hist:Hist, rank:[usize;257], length:[usize;257], pending:Option<(usize,usize,Option<usize>)>, bytes:usize, error:Option<String> }
thread_local! { static COLLECT:RefCell<Option<Collector>>=const{RefCell::new(None)}; }
pub fn start()->Result<(),String>{COLLECT.with(|cell|{let mut c=cell.borrow_mut();if c.is_some(){return Err("observer nested".into());}*c=Some(Collector{hist:Hist::new(),rank:[0;257],length:[0;257],pending:None,bytes:0,error:None});Ok(())})}
pub fn token(component:usize,context:usize,symbol:usize,token:usize,limit:usize){COLLECT.with(|cell|{let mut slot=cell.borrow_mut();let Some(c)=slot.as_mut() else{return;};if c.error.is_some(){return;}let result=(||{if symbol>=257{return Err("observer symbol".into());}if component==0 {if c.pending.is_some(){return Err("observer rank order".into());}c.hist.record(0,symbol,0,c.rank[symbol].min(3),token,limit,c.rank[symbol])?;c.pending=Some((symbol,token,None));}else if component==1{let Some((s,r,None))=c.pending else{return Err("observer length order".into());};if s!=symbol || context!=histogram::exponent(r+1){return Err("observer context".into());}c.hist.record(1,symbol,context,c.length[symbol],token,limit,c.rank[symbol])?;c.pending=Some((s,r,Some(token)));}else{return Err("observer component".into());}Ok(())})();if let Err(e)=result{c.error=Some(e);}})}
pub fn byte(){COLLECT.with(|cell|{if let Some(c)=cell.borrow_mut().as_mut(){match c.bytes.checked_add(1){Some(x)=>c.bytes=x,None=>c.error=Some("observer bytes overflow".into())}}})}
pub fn run_done(symbol:usize,rank:usize,length:usize){COLLECT.with(|cell|{let mut slot=cell.borrow_mut();let Some(c)=slot.as_mut() else{return;};if c.error.is_some(){return;}let result=(||{if symbol>=257 || length==0{return Err("observer run range".into());}if c.pending!=Some((symbol,rank,Some((length-1).min(255)))){return Err("observer run mismatch".into());}let mut expected=0; if length>=256{let mut n=length-256;loop{expected+=1;n>>=7;if n==0{break;}}}if c.bytes!=expected{return Err("observer escape bytes".into());}c.hist.done(c.bytes)?;c.rank[symbol]=rank;c.length[symbol]=histogram::length_bucket(length);c.pending=None;c.bytes=0;Ok(())})();if let Err(e)=result{c.error=Some(e);}})}
pub fn finish()->Result<Hist,String>{COLLECT.with(|cell|{let c=cell.borrow_mut().take().ok_or("observer not started")?;if let Some(e)=c.error{return Err(e);}if c.pending.is_some() || c.bytes!=0{return Err("observer incomplete".into());}c.hist.validate()?;Ok(c.hist)})}
